#[test]
fn test_every_row_opens_or_fails_as_named_and_decrypts_to_its_twin() {
    // Row: file, password, status, pages, digest, twin.
    let f: &[u8] = &crate::testport::test_file("pdf/p3.txt")[..];
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ctr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(f);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut rows: i32 = 0;
    let mut opened: i32 = 0;
    let mut e: i32 = 0;
    let mut s0: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut s3: i32 = 0;
    let mut s4: i32 = 0;
    let mut status: i32 = 0;
    while pos < n {
        line += 1;
        e = ct_nl(f, pos);
        if (pos < e) && (crate::port::blob_u8(f, pos) != 35) {
            rows += 1;
            s0 = ct_tab(f, pos, e);
            s1 = ct_tab(f, s0 + 1, e);
            s2 = ct_tab(f, s1 + 1, e);
            s3 = ct_tab(f, s2 + 1, e);
            s4 = ct_tab(f, s3 + 1, e);
            let t: &mut String = &mut crate::port::new_text();
            let file: &[u8] = &crate::testport::test_file_span(f, pos, s0)[..];
            status = ct_open(file, f, s0 + 1, s1, ar, dc, a, b, st, pg);
            pd_status_emit_name(t, status);
            crate::testport::assert_text_span(t, f, s1 + 1, s2, "status", line);
            if status == 0 {
                opened += 1;
                if ct_dash(f, s4 + 1, e) == 1 {
                    crate::testport::assert_eq_at(ct_verify(file, file, 0, ct_dec(f, s2 + 1, s3), ct_dec(f, s3 + 1, s4), ar, dc, a, b, st, pg, out, ctr), 0, "pages, geometry, content, title", line);
                } else {
                    crate::testport::assert_eq_at(ct_verify(file, &crate::testport::test_file_span(f, s4 + 1, e)[..], 1, ct_dec(f, s2 + 1, s3), ct_dec(f, s3 + 1, s4), ar, dc, a, b, st, pg, out, ctr), 0, "pages, geometry, content, title, equal to the twin", line);
                }
            }
        }
        pos = e + 1;
    }
    crate::testport::assert_that(rows > 70, "the rows were read");
    crate::testport::assert_that(opened > 50, "most rows open");
}
pub(crate) fn ct_window_in(c: &mut crate::port::Cells, rows: &[u8], ps: i32, pe: i32) -> i32 {
    // 1 when the first (up to 8) bytes of the password rows[ps, pe) occur, in
    // a row, among the cells of c.
    let mut w: i32 = pe - ps;
    let mut i: i32 = 0;
    let mut k: i32 = 0;
    let mut same: i32 = 0;
    if w > 8 {
        w = 8;
    }
    if w < 4 {
        return 0;
    }
    while (i + w) <= crate::port::cells_len(c) {
        same = 1;
        k = 0;
        while (same == 1) && (k < w) {
            if crate::port::cells_at(c, i + k) != crate::port::blob_u8(rows, ps + k) {
                same = 0;
            }
            k += 1;
        }
        if same == 1 {
            return 1;
        }
        i += 1;
    }
    return 0;
}
#[test]
fn test_a_password_is_not_left_in_the_arena_the_document_or_the_scratch() {
    // D058: the password rides with the input and is never written down. After
    // a complete open, the page walk and a read of page 1's content, none of
    // the cells kin holds contains it (its first bytes: 8 at most).
    let f: &[u8] = &crate::testport::test_file("pdf/p3.txt")[..];
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(f);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut checked: i32 = 0;
    let mut e: i32 = 0;
    let mut s0: i32 = 0;
    let mut s1: i32 = 0;
    let mut status: i32 = 0;
    let mut con: i32 = 0;
    while pos < n {
        line += 1;
        e = ct_nl(f, pos);
        if (pos < e) && (crate::port::blob_u8(f, pos) != 35) {
            s0 = ct_tab(f, pos, e);
            s1 = ct_tab(f, s0 + 1, e);
            if ct_dash(f, s0 + 1, s1) == 0 {
                let file: &[u8] = &crate::testport::test_file_span(f, pos, s0)[..];
                status = ct_open(file, f, s0 + 1, s1, ar, dc, a, b, st, pg);
                if status == 0 {
                    con = pd_pg_contents(pg, 0);
                    if con != 0 {
                        pd_stream_data(&crate::port::src_of_blob(file), ar, dc, a, b, st, con, out);
                    }
                }
                checked += 1;
                crate::testport::assert_eq_at(ct_window_in(ar, f, s0 + 1, s1), 0, "not in the arena", line);
                crate::testport::assert_eq_at(ct_window_in(dc, f, s0 + 1, s1), 0, "not in the document", line);
                crate::testport::assert_eq_at(ct_window_in(a, f, s0 + 1, s1), 0, "not in scratch a", line);
                crate::testport::assert_eq_at(ct_window_in(b, f, s0 + 1, s1), 0, "not in scratch b", line);
                crate::testport::assert_eq_at(ct_window_in(st, f, s0 + 1, s1), 0, "not in scratch st", line);
                crate::testport::assert_eq_at(ct_window_in(pg, f, s0 + 1, s1), 0, "not in the page table", line);
            }
        }
        pos = e + 1;
    }
    crate::testport::assert_that(checked > 40, "rows with a password were checked");
}
